<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driven;

use Override;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Connector\Pdo\TemplateSnippetPdoConnector;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetReadGateway;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetSlide;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetFilter;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetCursor;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\TemplateSnippetRef;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\TemplateSnippet;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateSnippetReadRepositoryAdapter implements TemplateSnippetReadGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplateSnippetPdoConnector $conn,
    ) {
    }
    #[Override]
    public function resolve(TemplateSnippetRef $ref): ?TemplateSnippet
    {
        if ($ref instanceof TemplateSnippet) {
            return $ref;
        } elseif (!$ref->_private_resolve) {
            $ref->_private_resolve = $this->conn->retrieve(new TemplateSnippetFilter(uids: [ $ref->uid() ]));
        }
        return $ref->_private_resolve;
    }
    #[Override]
    public function list(?TemplateSnippetFilter $filter = null, ?TemplateSnippetCursor $cursor = null): TemplateSnippetSlide
    {
        $this->logDebug("List for Template snippet on adapter ");
        $span = $this->startSpan("List for Template snippet on adapter");
        try {
            $values = $this->conn->list($filter, $cursor);
            $last = end($values);
            return new TemplateSnippetSlide(function (TemplateSnippetFilter $slide, ?TemplateSnippetCursor $next) use ($filter) {
                return $this->list($filter, $next);
            }, new TemplateSnippetCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieve(TemplateSnippetFilter $filter): ?TemplateSnippet
    {
        $this->logDebug("Retrieve for Template snippet on adapter ");
        $span = $this->startSpan("Retrieve for Template snippet on adapter");
        try {
            return $this->conn->retrieve($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function exists(TemplateSnippetFilter $filter): bool
    {
        $this->logDebug("Exists for Template snippet on adapter ");
        $span = $this->startSpan("Exists for Template snippet on adapter");
        try {
            return $this->conn->exists($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function count(?TemplateSnippetFilter $filter = null): int
    {
        $this->logDebug("Count for Template snippet on adapter ");
        $span = $this->startSpan("Count for Template snippet on adapter");
        try {
            return $this->conn->count($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneByCode(string $code): ?TemplateSnippet
    {
        $this->logDebug("Find on by code for Template snippet on adapter");
        $span = $this->startSpan("Find on by code for Template snippet on adapter");
        try {
            return $this->conn->retrieve(new TemplateSnippetFilter(code: $code));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneByCodeAndTenant(string $code, TenantRef $tenant): ?TemplateSnippet
    {
        $this->logDebug("Find on by code tenant for Template snippet on adapter");
        $span = $this->startSpan("Find on by code tenant for Template snippet on adapter");
        try {
            return $this->conn->retrieve(new TemplateSnippetFilter(codeAndTenant: TemplateSnippetFilter::codeAndTenantFilter(code: $code, tenant: $tenant)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
